export const dictionaries: Record<Locale, Record<LocaleKey, string>> = { fr, en };

function supportedLocale(value: string | null | undefined): Locale | null {
  if (!value) return null;
  const base = value.trim().toLowerCase().split("-")[0];
  return (supportedLocales as readonly string[]).includes(base) ? base as Locale : null;
}

export function resolveLocale(stored: string | null | undefined, browserLanguages: readonly string[] = []): Locale {
  const explicit = supportedLocale(stored);
  if (explicit) return explicit;
  for (const language of browserLanguages) {
    const locale = supportedLocale(language);
    if (locale) return locale;
  }
  return "fr";
}

export function translate(
  locale: Locale,
  key: LocaleKey,
  values: Record<string, string | number> = {},
): string {
  return dictionaries[locale][key].replace(/\{([a-zA-Z][a-zA-Z0-9]*)\}/g, (match, name: string) => (
    Object.prototype.hasOwnProperty.call(values, name) ? String(values[name]) : match
  ));
}
